<script setup lang="ts">
import {ref,reactive,computed,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,can} from './session'
const props=defineProps<{store:string,shipmentId:string,invoiceId?:number}>(),emit=defineEmits(['saved','close'])
const loading=ref(false),saving=ref(false),error=ref(''),ready=ref(false),revision=ref<number|null>(null),items=ref<any[]>([]),selected=ref<any[]>([]),packingTotal=ref(0),packingToken=ref('')
const header=reactive<any>({}),table=ref<any>(),editable=computed(()=>can('fba.invoice','operate'));let baseline=''
const state=()=>JSON.stringify({header,items:items.value})
const headerFields={tracking_code:'货件追踪编码（Reference ID）',country:'国家（二字代码）',warehouse_code:'亚马逊仓库代码',boxes:'箱数',vat:'VAT',eori:'EORI号',consignee:'收件人',city:'城市',province:'州 / 省份',address:'地址',postal_code:'邮编',dispatched_on:'发货日期'}
const fields:Record<string,string>={name_en:'产品英文品名',name_cn:'产品中文品名',unit_price:'产品申报单价',amount:'产品申报总价',currency:'申报币种',quantity:'产品单箱数量（申报数量）',total_quantity:'产品总数量',material_cn:'产品材质（中文）',material_en:'产品材质（英文）',hs_code:'产品海关编码（清关）',usage_cn:'产品用途（中文）',usage_en:'产品用途（英文）',brand:'产品品牌',model:'产品型号',weight_g:'单个产品重量（g）',clearance_url:'产品链接',image_url:'产品图片',battery:'是否带电',magnet:'是否带磁',tax_rate:'清关税率（%）',box_length_cm:'箱长（CM）',box_width_cm:'箱宽（CM）',box_height_cm:'箱高（CM）',box_weight_kg:'箱重（KG）'}
const numeric=['unit_price','quantity','total_quantity','weight_g','tax_rate','box_length_cm','box_width_cm','box_height_cm','box_weight_kg']
const boxFields=['box_label','box_length_cm','box_width_cm','box_height_cm','box_weight_kg']
function normalize(rows:any[]){return rows.map(row=>{const out={...row};for(const k of numeric)out[k]=out[k]==null?null:Number(out[k]);return out})}
async function load(){loading.value=true;error.value='';try{const d=await api(props.invoiceId?'/logistics/invoices/'+props.invoiceId:'/logistics/invoices/prepare?'+new URLSearchParams({store:props.store,shipment_id:props.shipmentId}));Object.assign(header,d.header);items.value=normalize(d.items);packingTotal.value=d.total_quantity;packingToken.value=d.packing_token||'';revision.value=d.revision;ready.value=true;baseline=state()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function updateBox(row:any,key:string){for(const other of items.value)if(other.box_key===row.box_key)other[key]=row[key]}
const customsFields=['name_cn','name_en','unit_price','currency','material_cn','material_en','hs_code','usage_cn','usage_en','brand','brand_type','model','tax_rate','origin','domestic_source','unit','clearance_url']
const matchFields=[...customsFields,...boxFields,'weight_g','image_url','battery','magnet']
const mergeReason=computed(()=>{const rows=selected.value;if(rows.length<2)return '请勾选至少两行';if(rows.some(r=>r.box_key!==rows[0].box_key))return '只能合并同箱明细';if(rows.some(r=>matchFields.some(k=>(r[k]??'')!==(rows[0][k]??''))))return '清关资料或箱规不一致';return ''})
async function merge(){if(mergeReason.value)return;saving.value=true;try{const row=await api('/logistics/invoices/merge',{items:selected.value}),ids=new Set(selected.value.map(r=>r.row_id)),index=items.value.findIndex(r=>ids.has(r.row_id));items.value=items.value.filter(r=>!ids.has(r.row_id));items.value.splice(index,0,...normalize([row]));selected.value=[];table.value?.clearSelection();ElMessage.success('已合并数量，保存后生效')}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
const totals=computed(()=>{const amounts:Record<string,number|null>={};for(const r of items.value){const c=r.currency;if(!(c in amounts))amounts[c]=0;if(r.unit_price==null||r.tax_rate==null)amounts[c]=null;else if(amounts[c]!=null)amounts[c]!+=r.unit_price*r.quantity*r.tax_rate/100}return amounts})
const weight=computed(()=>{const boxes=new Map(items.value.map(r=>[r.box_key,r.box_weight_kg]));return [...boxes.values()].some(v=>v==null)?null:[...boxes.values()].reduce((a,b)=>a+b,0)})
const chooser=ref(false),target=ref<any>(),profiles=ref<any[]>([]),profileQ=ref(''),profilePage=ref(1),profileTotal=ref(0),profileBusy=ref(false);let profileSeq=0
async function searchProfiles(){const n=++profileSeq;profileBusy.value=true;try{const d=await api('/customs/profiles?'+new URLSearchParams({q:profileQ.value,page:String(profilePage.value),page_size:'20'}));if(n===profileSeq){profiles.value=d.rows;profileTotal.value=d.total}}catch(e){ElMessage.error((e as Error).message)}finally{if(n===profileSeq)profileBusy.value=false}}
function replace(row:any){target.value=row;profileQ.value='';profilePage.value=1;chooser.value=true;searchProfiles()}
function countryCurrency(){return ({GB:'GBP',UK:'GBP',PL:'PLN',SE:'SEK',CN:'CNY'} as Record<string,string>)[String(header.country||'').toUpperCase()]||'EUR'}
function resetCurrencies(){for(const row of items.value)row.currency=countryCurrency();ElMessage.success('全部申报币种已恢复为 '+countryCurrency()+'，单价不变，保存后生效')}
async function choose(p:any){profileBusy.value=true;try{const data=await api('/customs/profiles/'+p.id),info=data.clearance||{},r=target.value;for(const key of customsFields)r[key]=['unit_price','tax_rate'].includes(key)?(info[key]==null?null:Number(info[key])):(info[key]|| (key==='currency'?'CNY':''));r.currency=countryCurrency();r.clearance_url=header.country==='GB'?info.clearance_url_uk||'':header.country==='DE'?info.clearance_url_de||'':'';r.profile_id=p.id;r.profile_name=p.name;chooser.value=false;ElMessage.success('已替换该行清关资料，保存后生效')}catch(e){ElMessage.error((e as Error).message)}finally{profileBusy.value=false}}
async function save(){if(saving.value||!ready.value)return;saving.value=true;error.value='';try{const d=await api('/logistics/invoices'+(props.invoiceId?'/'+props.invoiceId:''),{store:props.store,shipment_id:props.shipmentId,revision:revision.value,packing_token:packingToken.value,header:{...header,dispatched_on:header.dispatched_on||null},items:items.value});baseline=state();ElMessage.success('清关发票已保存');emit('saved',d)}catch(e){error.value=(e as Error).message;ElMessage.error(error.value)}finally{saving.value=false}}
async function canLeave(){if(saving.value)return false;if(!ready.value||state()===baseline)return true;try{await ElMessageBox.confirm('尚有未保存的发票资料，确定放弃修改？','离开发票',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',type:'warning'});return true}catch{return false}}
function unload(e:BeforeUnloadEvent){if(ready.value&&state()!==baseline){e.preventDefault();e.returnValue=''}}
defineExpose({canLeave});onMounted(()=>{load();window.addEventListener('beforeunload',unload)});onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
</script>
<template><section class="invoice-editor" v-loading="loading"><div class="invoice-toolbar"><h2>{{invoiceId?'编辑':'新增'}}清关发票 · {{shipmentId}}</h2><div><el-button @click="emit('close')">关闭</el-button><el-button v-if="editable" type="primary" :loading="saving" :disabled="!ready" @click="save">保存发票</el-button></div></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="!ready&&!loading" @click="load">重新加载</el-button>
<template v-if="ready"><h3>货件信息</h3><el-form label-position="top" class="invoice-basic" :disabled="!editable||saving"><el-form-item label="FBA号"><el-input :model-value="shipmentId" readonly/></el-form-item><el-form-item v-for="(label,key) in headerFields" :key="key" :label="label"><el-input-number v-if="key==='boxes'" v-model="header[key]" :min="1" :precision="0" :controls="false" :aria-label="label"/><el-date-picker v-else-if="key==='dispatched_on'" v-model="header[key]" type="date" value-format="YYYY-MM-DD" placeholder="选择发货日期"/><el-input v-else v-model="header[key]" :aria-label="label" :maxlength="key==='country'?2:key==='address'?1000:200" @change="key==='country'&&(header.country=header.country.toUpperCase()==='UK'?'GB':header.country.toUpperCase())"/></el-form-item></el-form>
<div class="invoice-detail-head"><h3>装箱商品明细</h3><el-tooltip :content="mergeReason||'同箱且清关资料一致，仅累加数量'"><span><el-button v-if="editable" :disabled="!!mergeReason||saving" @click="merge">合并所选行</el-button></span></el-tooltip><span>装箱单总数量：{{packingTotal}} · 当前申报数量：{{items.reduce((n,r)=>n+r.quantity,0)}} · 合并仅限同箱同资料</span></div>
<el-table ref="table" :data="items" row-key="row_id" border max-height="650" @selection-change="(rows:any[])=>selected=rows" class="invoice-items"><el-table-column type="selection" width="45" fixed="left" :selectable="()=>editable&&!saving"/><el-table-column label="箱号" width="230" fixed="left"><template #default="{row}"><el-input v-model="row.box_label" aria-label="箱号" :disabled="!editable||saving" @change="updateBox(row,'box_label')"/></template></el-table-column><el-table-column label="SKU / 品名" width="230"><template #default="{row}"><p class="invoice-sku">{{row.sku}}</p><small>{{row.profile_name||'未关联资料'}}</small></template></el-table-column>
<el-table-column v-for="(label,key) in fields" :key="key" :label="label" :width="['name_cn','name_en','clearance_url','image_url'].includes(key)?220:170"><template #header><span>{{label}}</span><el-button v-if="key==='currency'&&editable" link type="primary" :disabled="saving" aria-label="全部恢复国家默认币种" @click="resetCurrencies">默认</el-button></template><template #default="{row}"><span v-if="key==='amount'">{{row.unit_price==null?'待填写单价':(row.unit_price*row.quantity).toFixed(2)}}</span><el-input-number v-else-if="numeric.includes(key)" v-model="row[key]" :min="['quantity','total_quantity'].includes(key)?1:key.startsWith('box_')?0.0001:0" :max="key==='tax_rate'?100:10000000" :precision="['quantity','total_quantity'].includes(key)?0:4" :controls="false" :aria-label="label" :disabled="!editable||saving" @change="boxFields.includes(key)&&updateBox(row,key)"/><el-select v-else-if="key==='currency'" v-model="row[key]" :disabled="!editable||saving" :aria-label="label"><el-option v-for="c in ['GBP','EUR','PLN','SEK','CNY']" :value="c" :label="c"/></el-select><el-select v-else-if="key==='battery'||key==='magnet'" v-model="row[key]" :disabled="!editable||saving" :aria-label="label"><el-option :value="false" label="否"/><el-option :value="true" label="是"/></el-select><div v-else-if="key==='image_url'" class="invoice-image"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" style="height:60px;width:80px"/><el-input v-model="row.image_url" aria-label="产品图片链接" placeholder="产品上传图片或亚马逊图片链接" :disabled="!editable||saving"/></div><el-input v-else v-model="row[key]" :aria-label="label" :disabled="!editable||saving" @change="boxFields.includes(key)&&updateBox(row,key)"/></template></el-table-column>
<el-table-column label="操作" fixed="right" width="110"><template #default="{row}"><el-button link type="primary" :disabled="!editable||saving" @click="replace(row)">更换资料</el-button></template></el-table-column></el-table>
<div class="invoice-totals"><strong>预计关税：</strong><span v-for="(amount,c) in totals" :key="c">{{c}} {{amount==null?'待补齐单价或税率':amount.toFixed(2)}}</span><span>总重量：{{weight==null?'待补齐箱重':weight.toFixed(4)+' KG'}}</span><p>预计关税 = 申报单价 × 单箱申报数量 × 税率；不同币种分别显示。新增及更换资料时，申报币种按货件国家默认；单价保留资料中的数值，不作汇率换算，请核对。商品总价自动计算，同箱箱规同步修改。保存的修改只用于本票发票。</p></div>
<div class="invoice-bottom"><el-button @click="emit('close')">关闭</el-button><el-button v-if="editable" type="primary" :loading="saving" @click="save">保存发票</el-button></div></template>
<el-dialog v-model="chooser" title="更换清关&报关资料" width="850px"><div class="profile-search"><el-input v-model="profileQ" aria-label="搜索资料商品名称" placeholder="搜索商品名称" @keyup.enter="profilePage=1;searchProfiles()"/><el-button @click="profilePage=1;searchProfiles()">查询</el-button></div><el-table :data="profiles" v-loading="profileBusy" border><el-table-column prop="name" label="商品名称"/><el-table-column label="英文清关名"><template #default="{row}">{{row.clearance?.name_en}}</template></el-table-column><el-table-column label="海关编码"><template #default="{row}">{{row.clearance?.hs_code}}</template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" :disabled="profileBusy" @click="choose(row)">选择</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="profilePage" :total="profileTotal" :page-size="20" layout="prev,pager,next,total" @current-change="searchProfiles"/></el-dialog>
</section></template>
<style scoped>.invoice-editor{background:white;margin:20px auto;padding:24px;max-width:1800px;border:1px solid #dce6e1;border-radius:8px}.invoice-toolbar{display:flex;justify-content:space-between;align-items:center;padding-bottom:20px;border-bottom:1px solid #e4ece8;gap:16px}.invoice-toolbar h2{font-size:18px}.invoice-basic{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:0 16px}.invoice-basic :deep(.el-input-number),.invoice-basic :deep(.el-date-editor){width:100%}.invoice-detail-head{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.invoice-detail-head span,.invoice-totals p,.invoice-sku,small{font-size:12px;color:#7a8c84}.invoice-items :deep(.el-input-number){width:100%}.invoice-totals{padding:24px 0;display:flex;gap:20px;flex-wrap:wrap}.invoice-totals p{width:100%;margin:0}.invoice-bottom{display:flex;justify-content:flex-end;padding-top:16px;border-top:1px solid #e4ece8}.profile-search{display:flex;gap:12px;margin-bottom:16px}.profile-search .el-input{width:320px}@media(max-width:1100px){.invoice-basic{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:650px){.invoice-basic{grid-template-columns:repeat(2,minmax(0,1fr))}.invoice-toolbar{flex-wrap:wrap}}</style>
